function syncVolumeControl(){applyAudioVolumes();syncAudioSettingsUi()}
setTimeout(()=>syncVolumeControl(),0);
function ac(){return audioCtx||(audioCtx=new(window.AudioContext||window.webkitAudioContext)())}
function tone(freq=440,dur=.09,type='sine',vol=.055,delay=0){if(!soundOn)return;try{const c=ac(),o=c.createOscillator(),g=c.createGain(),t=c.currentTime+delay;o.type=type;o.frequency.setValueAtTime(freq,t);g.gain.setValueAtTime(vol*sfxVolume(),t);g.gain.exponentialRampToValueAtTime(.001,t+dur);o.connect(g);g.connect(c.destination);o.start(t);o.stop(t+dur)}catch{}}
function playSfx(k){if(!soundOn)return;if(k==='click')tone(520,.045,'sine',.025);if(k==='start'){tone(392,.08);tone(523,.1,'sine',.05,.09);tone(659,.13,'sine',.05,.18)}if(k==='night'){tone(220,.28,'sine',.05);tone(164,.35,'sine',.035,.12)}if(k==='day'){tone(523,.1);tone(659,.1,'sine',.05,.1);tone(784,.18,'sine',.05,.2)}if(k==='gun'){tone(85,.08,'square',.12);tone(48,.18,'sawtooth',.08,.04)}if(k==='role'){tone(110,.34,'sine',.07);tone(165,.34,'sine',.06,.16);tone(330,.18,'triangle',.07,.55);tone(494,.26,'sine',.065,.72)}if(k==='vote'){tone(740,.06);tone(880,.08,'sine',.04,.08)}if(k==='win'){tone(523,.08);tone(659,.08,'sine',.05,.09);tone(784,.08,'sine',.05,.18);tone(1047,.22,'sine',.06,.27)}if(k==='warning'){tone(920,.09,'square',.075);tone(760,.09,'square',.065,.12)}}
document.addEventListener('pointerdown',e=>{if(e.target.closest('button'))playSfx('click')},{passive:true});

const mafiaNightBgm=new Audio('/mafia-night.mp3'),mafiaDayBgm=new Audio('/mafia-day.mp3'),mafiaVoteBgm=new Audio('/mafia-vote.mp3'),mafiaGunSfx=new Audio('/mafia-gun.mp3');
[mafiaNightBgm,mafiaDayBgm,mafiaVoteBgm].forEach(a=>a.loop=true);
let lastMafiaDealer='';
function mafiaStopAudio(){[mafiaNightBgm,mafiaDayBgm,mafiaVoteBgm].forEach(a=>{a.pause();a.currentTime=0})}
function mafiaPlayGun(){if(!soundOn)return;try{mafiaGunSfx.currentTime=Math.min(.5,mafiaGunSfx.duration||.5);mafiaGunSfx.volume=sfxVolume();mafiaGunSfx.play().catch(()=>{})}catch{}}
function speakMafiaDealer(text){if(!text)return;try{speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='ko-KR';u.rate=1.42;u.pitch=.88;u.volume=narrationOn?narrationVolume():0;speechSynthesis.speak(u)}catch{}}
function syncMafiaAudio(){
  if(!state||state.game!=='mafia'){mafiaStopAudio();return}
  const base=bgmVolume();[mafiaNightBgm,mafiaDayBgm,mafiaVoteBgm].forEach(a=>a.volume=base);
  if(!bgmOn){mafiaStopAudio()}else{
    const target=state.phase==='mafiaNight'?mafiaNightBgm:(['mafiaVote','mafiaDefense','mafiaExecuteVote','terroristPick'].includes(state.phase)?mafiaVoteBgm:(state.phase==='mafiaDay'?mafiaDayBgm:null));
    [mafiaNightBgm,mafiaDayBgm,mafiaVoteBgm].forEach(a=>{if(a!==target)a.pause()});
    if(target&&target.paused)target.play().catch(()=>{});
  }
  
}

