function showEventPopup(text,cls='',duration=2400){let e=document.getElementById('eventPopup');if(!e){e=document.createElement('div');e.id='eventPopup';document.body.appendChild(e)}e.className='event-popup show '+cls;e.textContent=text;clearTimeout(e._t);e._t=setTimeout(()=>e.classList.remove('show'),duration)}
