$('#createBtn').onclick=()=>{if(['genius','deathmatch'].includes(game)&&!geniusProfile)return openGeniusAuth(game==='deathmatch'?'createDeathmatch':'create');const p=profile();if(['genius','deathmatch'].includes(game)&&geniusProfile){p.name=geniusProfile.name;p.avatar='💎'}else if(!p.name)return toast('닉네임을 입력해주세요.');socket.emit('createRoom',{...p,game,mode,password:$('#createPassword').value},r=>{if(r.ok)return enter(r);if(r.error==='GENIUS_AUTH_REQUIRED')return openGeniusAuth('create');toast(r.error)})};
