const labels={liar:'🎭 라이어게임',mafia:'🌙 마피아게임',truth:'💬 진실게임',rummi:'🔢 루미큐브',wordchain:'🔗 끝말잇기',genius:'💎 지니어스게임',stockwar:'📈 주식전쟁',deathmatch:'🃏 데스매치',indianpoker:'🃏 인디언 포커'};
