function renderPlayers(){const mafiaVisible=new Set(priv?.game==='mafia'?(priv.mafiaIds||[]):[]);const talkPhase=state.game==='liar'&&((state.mode==='normal'&&state.phase==='play')||(state.mode==='question'&&state.phase==='reveal'));const rTurn=state.game==='rummi'?state.rummi?.turnPlayerId:null,wTurn=state.game==='wordchain'?state.wordchain?.turnPlayerId:null;$('#players').innerHTML=state.players.map((p,pi)=>{const dead=state.game==='mafia'&&!p.alive,maf=state.game==='mafia'&&mafiaVisible.has(p.id),starter=talkPhase&&p.id===state.discussionStarterId,rTurnNow=state.game==='rummi'&&p.id===rTurn,wTurnNow=state.game==='wordchain'&&p.id===wTurn,wDead=state.game==='wordchain'&&state.wordchain?.eliminated?.[p.id];let status=p.connected?'<span class="status-online">● 접속 중</span>':'<span class="status-offline">접속 끊김 🔌</span>';if(p.rolePublic)status=`역할: ${role(p.rolePublic)}`;if(state.game==='rummi'&&state.rummi?.rackCounts)status=`남은 타일 <b>${state.rummi.rackCounts[p.id]??0}개</b>`;if(state.game==='wordchain'&&state.wordchain)status=`${'❤️'.repeat(state.wordchain.lives?.[p.id]||0)}${wDead?' · 💀 탈락':''}`;if(['genius','stockwar','deathmatch','indianpoker'].includes(state.game)&&p.geniusName)status=`<span class="genius-stat">💎 가넷 ${p.geniusGarnets??0}</span><span class="genius-stat">🏆 우승 ${p.geniusWins??0}회</span>`;const starterBadge=starter?`<div class="first-speaker ${state.discussionDirection==='left'?'left':'right'}">${state.discussionDirection==='left'?'← 선':'선 →'}</div>`:'';const incoming=state.game==='stockwar'&&p.id!==me?(priv?.messages||[]).filter(m=>!m.own&&m.from===p.id).length:0,unread=Math.max(0,incoming-(stockReadCounts[p.id]||0));const stockActions=state.game==='stockwar'&&p.id!==me?`<div class="stock-player-actions"><button data-stock-chat="${p.id}">대화${unread?` <span class="chat-bubble">${unread}</span>`:''}</button><button data-stock-pay="${p.id}">송금</button></div>`:'';const geniusMode=['genius','stockwar','deathmatch','indianpoker'].includes(state.game),gi=Number.isInteger(p.geniusColorIndex)?p.geniusColorIndex:pi%10,gcols=['#ef4444','#f97316','#facc15','#22c55e','#3b82f6','#a855f7','#38bdf8','#f8fafc','#8b5e3c','#111111'],gicons=['♥','♥','♥','♥','♥','♥','♥','♥','♥','♥'];return `<div data-player-id="${p.id}" class="player ${dead?'dead':''} ${maf?'mafia-mark':''} ${starter?'first-speaker-player':''} ${rTurnNow?'rummi-current-player':''} ${wTurnNow?'wordchain-current-player':''} ${wDead?'wordchain-dead':''} ${geniusMode?'genius-player':''} ${geniusMode&&p.geniusFrame?p.geniusFrame:''} ${p.voiceSpeaking?'voice-speaking':''} ${state.game==='mafia'&&priv?.loverId===p.id?'lover-player':''}" ${geniusMode?`style="--player-color:${gcols[gi]}"`:''}>${starterBadge}<div class="face">${geniusMode?`<span class="genius-token">${gicons[gi]}</span>`:avatarHtml(p.avatar)}</div><div class="name">${esc(p.name)} ${p.id===state.hostId?'👑':''}${p.isBot?'<span class="bot-badge">🤖 BOT</span>':''}</div><div class="score">${status}</div>${dead?'<div class="death-badge">💀 사망</div>':''}${maf?'<div class="mafia-badge">🔪 마피아</div>':''}${p.geniusBadge?`<div class="genius-badge-label">${esc(p.geniusBadge)}</div>`:''}${stockActions}</div>`}).join('');bindStockPlayerActions()}

function bindPlayerKick(){if(!host())return;$$('#players .player').forEach((el,i)=>el.oncontextmenu=e=>{e.preventDefault();const p=state.players[i];if(!p||p.id===me)return;if(confirm(`${p.name}님을 방에서 내보낼까요?`))socket.emit('kickPlayer',{playerId:p.id},r=>!r.ok&&toast(r.error))})}
function mafiaRoleSummary(n){if(n<5)return '5명 이상 모이면 직업 구성이 표시됩니다.';let a=[];const add=(x,c=1)=>{if(c)a.push(`${x} ${c}`)};add('🔪 마피아',n>=8?2:1);if(n>=10)add('🕵️ 스파이');add('🚓 경찰');add('🩺 의사');if(n>=6)add('🪖 군인');if(n>=7)add('📰 기자');if(n>=9)add('🗳️ 정치인');if(n>=11)add('💣 테러리스트');let used=(n>=8?2:1)+(n>=10?1:0)+2+(n>=6?1:0)+(n>=7?1:0)+(n>=9?1:0)+(n>=11?1:0);add('🏘️ 시민',n-used);return a.join(' · ')+(n>=12?' · 💘 이 중 2명은 연인':'')}
function truthGenderPanel(){const p=state.players.find(x=>x.id===me),picked=p?.gender;const ready=state.players.filter(x=>x.connected&&!x.isBot&&x.gender).length,total=state.players.filter(x=>x.connected&&!x.isBot).length;return `<div class="truth-gender-box"><div><b>나의 성별</b><span class="muted"> · 질문 구성에 참고됩니다. (${ready}/${total} 선택)</span></div><div class="gender-buttons"><button data-gender="female" class="${picked==='female'?'active':''}">♀ 여자</button><button data-gender="male" class="${picked==='male'?'active':''}">♂ 남자</button></div></div>`}
function bindTruthGender(){document.querySelectorAll('[data-gender]').forEach(b=>b.onclick=()=>socket.emit('setGender',{gender:b.dataset.gender},r=>!r.ok&&toast(r.error)))}
function renderSettings(){
 const e=$('#settings');if(!host()||state.phase!=='lobby'){e.classList.add('hidden');return}e.classList.remove('hidden');
 let h=`<h3>방 설정</h3><div class="settings-grid">${state.game==='genius'?'':`<label>게임 변경<select id="sGame">${Object.entries(labels).filter(([k])=>!['genius','stockwar','deathmatch','indianpoker'].includes(k)).map(([k,v])=>`<option value="${k}" ${state.game===k?'selected':''}>${v} · ${mins[k]}~${maxes[k]}명</option>`).join('')}</select></label>`}`;
 if(state.game==='deathmatch')h+=`<label>데스매치 게임<select id="sDeathmatchGame"><option value="indianpoker" selected>인디언 포커 · 2명</option></select></label><label>가넷 베팅<select id="sDeathmatchBet"><option value="1" ${state.settings.deathmatchGarnetBet==1?'selected':''}>1 가넷</option><option value="2" ${state.settings.deathmatchGarnetBet==2?'selected':''}>2 가넷</option><option value="3" ${state.settings.deathmatchGarnetBet==3?'selected':''}>3 가넷</option><option value="5" ${state.settings.deathmatchGarnetBet==5?'selected':''}>5 가넷</option></select></label><div class="deathmatch-lobby-card"><b>인디언 포커</b><p>2인 모두 로그인해야 하며, 선택한 가넷을 걸고 승부합니다. 승자가 베팅된 가넷을 가져갑니다.</p></div>`;
 if(state.game==='genius')h+=`<label>지니어스게임 선택<select id="sGeniusGame"><option value="stockwar" selected>📈 주식전쟁 · 4~10명</option></select></label><label>가넷 매치<select id="sGarnetMatch"><option value="0" ${!state.settings.stockGarnetMatch?'selected':''}>OFF</option><option value="1" ${state.settings.stockGarnetMatch?'selected':''}>ON · 참가자당 1가넷</option></select></label>`;
 if(state.game==='liar')h+=`<label>세부 게임<select id="sMode"><option value="normal" ${state.mode==='normal'?'selected':''}>단어게임</option><option value="question" ${state.mode==='question'?'selected':''}>질문게임</option></select></label>${state.mode==='normal'?`<label>라이어 모드<select id="sRoleMode"><option value="liar" ${state.settings.liarRoleMode==='liar'?'selected':''}>일반모드 · 라이어는 단어를 모름</option><option value="spy" ${state.settings.liarRoleMode==='spy'?'selected':''}>바보모드 · 라이어는 다른 단어를 앎</option><option value="random" ${state.settings.liarRoleMode==='random'?'selected':''}>랜덤 🎲</option></select></label>`:''}<label>라이어 수<select id="sLiar"><option ${state.settings.liarCount==1?'selected':''}>1</option><option ${state.settings.liarCount==2?'selected':''}>2</option><option ${state.settings.liarCount==3?'selected':''}>3</option></select></label>`;
 if(state.game==='truth')h+=`<label>질문 단계<select id="sTruth"><option value="easy" ${state.settings.truthLevel==='easy'?'selected':''}>이지 😊</option><option value="normal" ${state.settings.truthLevel==='normal'?'selected':''}>노멀 😏</option><option value="hard" ${state.settings.truthLevel==='hard'?'selected':''}>하드 🔥</option></select></label>`;
 if(state.game==='wordchain')h+=`<label>게임 모드<select id="sWMode"><option value="normal" ${state.settings.wordchainMode==='normal'?'selected':''}>일반 모드</option><option value="speed" ${state.settings.wordchainMode==='speed'?'selected':''}>스피드 · 5초</option><option value="item" ${state.settings.wordchainMode==='item'?'selected':''}>아이템 모드</option></select></label><label>턴 시간<select id="sWTime"><option value="5" ${state.settings.wordchainTurnTime==5?'selected':''}>5초</option><option value="7" ${state.settings.wordchainTurnTime==7?'selected':''}>7초</option><option value="10" ${state.settings.wordchainTurnTime==10?'selected':''}>10초</option><option value="15" ${state.settings.wordchainTurnTime==15?'selected':''}>15초</option><option value="20" ${state.settings.wordchainTurnTime==20?'selected':''}>20초</option></select></label><label>목숨<select id="sWLives"><option value="1" ${state.settings.wordchainLives==1?'selected':''}>1개</option><option value="2" ${state.settings.wordchainLives==2?'selected':''}>2개</option><option value="3" ${state.settings.wordchainLives==3?'selected':''}>3개</option><option value="5" ${state.settings.wordchainLives==5?'selected':''}>5개</option></select></label><label>한방단어<select id="sWOne"><option value="0" ${!state.settings.wordchainOneShot?'selected':''}>허용 · 공격 가능</option><option value="1" ${state.settings.wordchainOneShot?'selected':''}>금지 · 매너 모드</option></select></label><div class="wordchain-rule-note">🇰🇷 두음법칙은 기본 적용됩니다.</div>`;
 if(['liar','mafia'].includes(state.game))h+=`<label>진행 시간<select id="sRound"><option value="0" ${!state.settings.roundTime?'selected':''}>제한없음</option><option value="60" ${state.settings.roundTime==60?'selected':''}>60초</option><option value="120" ${state.settings.roundTime==120?'selected':''}>120초</option><option value="180" ${state.settings.roundTime==180?'selected':''}>180초</option><option value="300" ${state.settings.roundTime==300?'selected':''}>300초</option></select></label><label>투표 시간<select id="sVote"><option value="20" ${state.settings.voteTime==20?'selected':''}>20초</option><option value="30" ${state.settings.voteTime==30?'selected':''}>30초</option><option value="60" ${state.settings.voteTime==60?'selected':''}>60초</option></select></label>`;
 if(state.game==='rummi')h+=`<label>한 사람 턴 시간<select id="sRummiTime"><option value="45" ${state.settings.rummiTurnTime==45?'selected':''}>45초</option><option value="60" ${state.settings.rummiTurnTime==60?'selected':''}>60초</option><option value="90" ${state.settings.rummiTurnTime==90?'selected':''}>90초</option><option value="120" ${state.settings.rummiTurnTime==120?'selected':''}>120초</option></select></label>`;
 h+='</div><button id="save" class="primary">설정 저장</button>';e.innerHTML=h;
 if($('#sGame'))$('#sGame').onchange=()=>{if($('#sGame').value!==state.game)socket.emit('switchGame',{game:$('#sGame').value},r=>{if(!r.ok)toast(r.error)})};
 if($('#sGeniusGame'))$('#sGeniusGame').onchange=()=>socket.emit('updateSettings',{geniusGame:$('#sGeniusGame').value},r=>!r.ok&&toast(r.error));
 if($('#sMode'))$('#sMode').onchange=()=>socket.emit('updateSettings',{mode:$('#sMode').value},r=>!r.ok&&toast(r.error));
 $('#save').onclick=()=>{const d={};if($('#sMode'))d.mode=$('#sMode').value;if($('#sRoleMode'))d.liarRoleMode=$('#sRoleMode').value;if($('#sLiar'))d.liarCount=+$('#sLiar').value;if($('#sTruth'))d.truthLevel=$('#sTruth').value;if($('#sRound'))d.roundTime=+$('#sRound').value;if($('#sVote'))d.voteTime=+$('#sVote').value;if($('#sRummiTime'))d.rummiTurnTime=+$('#sRummiTime').value;if($('#sWMode'))d.wordchainMode=$('#sWMode').value;if($('#sWTime'))d.wordchainTurnTime=+$('#sWTime').value;if($('#sWLives'))d.wordchainLives=+$('#sWLives').value;if($('#sWOne'))d.wordchainOneShot=$('#sWOne').value==='1';if($('#sGeniusGame'))d.geniusGame=$('#sGeniusGame').value;if($('#sDeathmatchGame'))d.deathmatchGame=$('#sDeathmatchGame').value;if($('#sDeathmatchBet'))d.deathmatchGarnetBet=+$('#sDeathmatchBet').value;if($('#sGarnetMatch'))d.stockGarnetMatch=$('#sGarnetMatch').value==='1';if($('#sRankHidden'))d.stockRankHidden=$('#sRankHidden').value==='1';socket.emit('updateSettings',d,r=>toast(r.ok?'설정을 저장했습니다.':r.error))}
}
function renderHost(){const e=$('#hostControls');let buttons='';if(state.phase==='lobby'){buttons='<button id="mainHome" class="ghost">메인화면</button>';if(host())buttons+='<button id="start" class="primary compact">게임 시작</button>';}else if(host()&&state.game==='liar'&&['play','reveal'].includes(state.phase))buttons='<button id="openVote">투표 시작</button>';else if(host()&&state.game==='mafia'&&state.phase==='mafiaDay')buttons='<button id="openVote">낮 투표 시작</button>';else if(host()&&state.game==='truth'&&state.phase==='truth')buttons='<button id="reroll">다른 질문</button><button id="next" class="primary compact">다음 사람</button>';else if(host()&&['result','mafiaResult','rummiResult','wordchainResult','stockFinal','vaultFinal','indianResult'].includes(state.phase))buttons='<button id="lobby">대기실</button><button id="next" class="primary compact">한 판 더</button>';if(host()&&state.phase!=='lobby')buttons+='<button id="endGame" class="danger compact">게임 종료</button>';e.innerHTML=buttons;if($('#mainHome'))$('#mainHome').onclick=()=>{if(host()&&!confirm('방장이 메인화면으로 나가면 방이 종료됩니다. 나갈까요?'))return;socket.emit('leaveRoom',{},()=>home())};if($('#start'))$('#start').onclick=()=>socket.emit('startGame',{},r=>!r.ok&&toast(r.error));if($('#openVote'))$('#openVote').onclick=()=>socket.emit('openVoting',{},r=>!r.ok&&toast(r.error));if($('#reroll'))$('#reroll').onclick=()=>socket.emit('truthReroll',{});if($('#next'))$('#next').onclick=()=>socket.emit('nextRound',{});if($('#lobby'))$('#lobby').onclick=()=>socket.emit('backToLobby',{});if($('#endGame'))$('#endGame').onclick=()=>{if(confirm('현재 게임을 완전히 종료하고 대기실로 돌아갈까요?'))socket.emit('endGame',{},r=>!r.ok&&toast(r.error))}}

