function geniusShopHtml(homeMode=false){const mine=homeMode?geniusProfile:state?.players?.find(p=>p.id===me),owned=mine?.owned||mine?.geniusOwned||[],frame=mine?.equippedFrame||mine?.geniusFrame||'',badge=mine?.equippedBadge||mine?.geniusBadge||'',wins=mine?.wins??mine?.geniusWins??0,garnets=mine?.garnets??mine?.geniusGarnets??0;return `<div class="genius-shop"><div class="genius-shop-head"><div><b>가넷상점 💎</b><span>테두리 · 칭호 · 컬렉션</span></div><strong>${garnets} 💎 · 🏆 ${wins}승</strong></div><div class="genius-shop-grid">${geniusShopCatalog.map(it=>{const has=owned.includes(it.id),eq=(it.type==='frame'&&frame===it.id)||(it.type==='badge'&&badge===it.preview),locked=wins<(it.wins||0);return `<div class="shop-item ${it.type}"><div class="shop-preview ${it.id}">${it.preview}</div><b>${it.name}</b><small>${it.type==='collect'?'컬렉션':it.type==='frame'?'프로필 테두리':'프로필 칭호'} · ${it.wins?`🏆 ${it.wins}승 이상`:'승수 조건 없음'}</small>${has&&it.type!=='collect'?`<button data-shop-equip="${it.id}" class="compact">${eq?'장착 중':'장착'}</button>`:has?'<span class="owned">보유 중</span>':`<button data-shop-buy-item="${it.id}" class="compact" ${locked?'disabled':''}>${locked?`🏆 ${it.wins}승 필요`:`${it.price}💎 구매`}</button>`}</div>`}).join('')}</div></div>`}
function refreshHomeProfile(p){if(!p)return;geniusProfile=p;$('#geniusHomeProfile').classList.remove('hidden');$('#homeGarnetShopBtn')?.classList.remove('hidden');$('#geniusHomeProfile').innerHTML=`<b>💎 ${esc(p.name)}</b><span>가넷 ${p.garnets} · 우승 ${p.wins}회</span>`}
function openGarnetShop(homeMode=false){const modal=$('#garnetShopModal'),body=$('#garnetShopModalBody');if(!modal||!body)return;if(homeMode&&!geniusProfile)return openGeniusAuth();body.innerHTML=geniusShopHtml(homeMode);modal.dataset.home=homeMode?'1':'0';modal.classList.remove('hidden');bindGeniusShop(homeMode)}
function renderGeniusShopPanel(){const panel=$('#geniusShopPanel');if(!panel)return;const myP=state?.players?.find(p=>p.id===me),show=state?.game==='genius'&&state?.phase==='lobby'&&myP?.geniusName;if(!show){panel.classList.add('hidden');panel.innerHTML='';return}panel.classList.remove('hidden');panel.innerHTML=`<button id="lobbyGarnetShopBtn" class="garnet-shop-toggle">가넷상점 💎 <span>테두리 · 칭호 · 컬렉션</span></button>`;$('#lobbyGarnetShopBtn').onclick=()=>openGarnetShop(false)}
function bindGeniusShop(homeMode=false){$$('[data-shop-buy-item]').forEach(b=>b.onclick=()=>socket.emit(homeMode?'geniusShopBuyGlobal':'geniusShopBuy',{itemId:b.dataset.shopBuyItem},r=>{toast(r.ok?'구매했습니다.':r.error);if(r.ok){if(r.profile)refreshHomeProfile(r.profile);if(homeMode)openGarnetShop(true);else render()}}));$$('[data-shop-equip]').forEach(b=>b.onclick=()=>socket.emit(homeMode?'geniusShopEquipGlobal':'geniusShopEquip',{itemId:b.dataset.shopEquip},r=>{toast(r.ok?'장착했습니다.':r.error);if(r.ok){if(r.profile)refreshHomeProfile(r.profile);if(homeMode)openGarnetShop(true);else render()}}))}
$('#homeGarnetShopBtn').onclick=()=>openGarnetShop(true);$('#garnetShopClose').onclick=()=>$('#garnetShopModal').classList.add('hidden');
function renderGame(){if(state.phase==='lobby'){const desc={liar:'단어 게임 / 질문 게임 중에서 선택해 플레이할 수 있습니다.',mafia:'밤의 능력과 낮 투표로 마피아를 찾아내세요.',truth:'한국형 진실게임 질문이 차례대로 나옵니다.',rummi:'14개 타일로 시작해 유효한 조합을 만들어 먼저 패를 비우세요.',wordchain:'순서대로 단어를 이어 목숨을 지키고 마지막까지 살아남으세요.',genius:'전략·협상·심리전 게임을 이 방에서 선택해 플레이합니다.',stockwar:'정보는 무기가 되고, 협상은 기회가 됩니다. 시장과 사람을 읽어 8번의 승부 끝에 최고의 자산가가 되십시오.',deathmatch:'1:1 심리전 게임을 선택해 승부합니다.',indianpoker:'상대 카드만 보고 베팅하는 1:1 심리전입니다.'}[state.game];const n=state.players.filter(p=>p.connected).length;const geniusLobby=state.game==='genius'?`<div class="genius-game-selector-view"><div class="genius-mini-game selected"><b>📈 주식전쟁</b><span>선택됨</span><p>정보는 무기가 되고, 협상은 기회가 됩니다. 시장과 사람을 읽어 8번의 승부 끝에 최고의 자산가가 되십시오.</p></div></div>`:'';$('#mainCard').innerHTML=`<div class="big">${labels[state.game]}</div><p>${desc}</p><p>현재 ${n}명 · ${mins[state.game]}~${maxes[state.game]}명 플레이</p>${state.game==='mafia'?`<div class="mafia-composition"><b>이번 인원 기준 직업</b><div>${mafiaRoleSummary(n)}</div></div>`:''}${geniusLobby}`;const myP=state.players.find(p=>p.id===me);let lobbyAction=state.game==='truth'?truthGenderPanel():(['genius','deathmatch'].includes(state.game)&&!myP?.geniusName?'<div class="genius-login-needed"><b>💎 두뇌게임 프로필 로그인이 필요합니다.</b><button id="roomGeniusLogin" class="primary compact">로그인 / 새 프로필</button></div>':'');$('#actionArea').innerHTML=lobbyAction;if(state.game==='truth')bindTruthGender();if($('#roomGeniusLogin'))$('#roomGeniusLogin').onclick=()=>openGeniusAuth();bindGeniusShop();renderGeniusShopPanel();return}if(state.game==='liar')renderLiar();else if(state.game==='truth')renderTruth();else if(state.game==='mafia')renderMafia();else if(state.game==='rummi')renderRummi();else if(state.game==='wordchain')renderWordchain();else if(state.game==='stockwar')renderStockwar();else if(state.game==='indianpoker')renderIndianPoker()}
function voteUI(e,ps){const eligible=ps.filter(p=>p.id!==me&&p.connected&&(state.game!=='mafia'||p.alive)),total=state.game==='mafia'?state.players.filter(p=>p.connected&&p.alive).length:state.players.filter(p=>p.connected).length;const progress=`<div class="vote-progress">🗳️ 투표 ${state.votesSubmitted.length}/${total}</div>`;if(state.votesSubmitted.includes(me)){e.innerHTML=progress+'<p>투표 완료! 다른 플레이어를 기다리는 중…</p>';return}e.innerHTML=progress+'<h3>한 명을 선택하세요</h3><div class="vote-grid">'+eligible.map(p=>`<button class="vote-btn" data-id="${p.id}"><span class="face">${avatarHtml(p.avatar)}</span>${esc(p.name)}</button>`).join('')+'</div>';e.querySelectorAll('[data-id]').forEach(b=>b.onclick=()=>socket.emit('vote',{targetId:b.dataset.id},r=>!r.ok&&toast(r.error)))}
function renderLiar(){const c=$('#mainCard'),a=$('#actionArea');if(!priv)return;if(state.mode==='normal'){const roleLabel=priv.isSpy?'🕵️ 스파이':priv.isLiar?'🤫 라이어':'✅ 시민';c.innerHTML=`<div class="eyebrow">카테고리 · ${esc(priv.category)}</div><div class="big ${priv.isLiar?'liar':''}">${roleLabel}</div>${priv.word?`<div class="big pop">${esc(priv.word)}</div>`:'<p>제시어를 모릅니다. 카테고리와 대화를 잘 활용하세요.</p>'}${priv.roleMode==='spy'?'<p>스파이 모드: 서로 비슷하지만 다른 제시어가 섞여 있습니다.</p>':''}`;}else c.innerHTML=priv.isLiar?`<div class="big liar">🤫 라이어</div><p>질문은 비밀입니다.</p><div class="big">범위 ${priv.min}~${priv.max}</div>`:`<div class="big question">${esc(priv.question)}</div><p>숫자 범위 ${priv.min}~${priv.max}</p>`;
if(state.mode==='question'&&state.phase==='play'&&!state.submitted.includes(me)){a.innerHTML=`<div class="join"><input id="ans" type="number" min="${priv.min}" max="${priv.max}" placeholder="${priv.min}~${priv.max}"><button id="ansBtn">답변</button></div><p class="muted">모두 제출하면 답변이 동시에 공개됩니다.</p>`;$('#ansBtn').onclick=()=>socket.emit('submitAnswer',{value:$('#ans').value},r=>!r.ok&&toast(r.error));}else if(state.answersRevealed&&['reveal'].includes(state.phase)){a.innerHTML='<h3>📊 모두의 답변</h3>'+state.players.map(p=>`<div class="answer-card"><span>${avatarHtml(p.avatar,'mini-avatar')} ${esc(p.name)}</span><b>${state.answers[p.id]??'미제출'}</b></div>`).join('');}else a.innerHTML='';
if(state.phase==='vote')voteUI(a,state.players);
if(state.phase==='liarCaught')a.innerHTML='<div class="result"><h2>🎯 라이어를 맞혔습니다!</h2><p>잠시 후 라이어에게 마지막 정답 추측 기회가 주어집니다.</p></div>';
if(state.phase==='liarGuess'){a.innerHTML=priv.canGuess?`<div class="result warning"><h2>🤔 마지막 정답 추측</h2><p>💡 정답은 <b>${priv.wordLength}글자</b>입니다.</p><div class="join"><input id="guess" autocomplete="off"><button id="guessBtn">정답 제출</button></div></div>`:'<div class="result"><h2>🧠 라이어가 정답을 추측 중입니다…</h2><p>25초 안에 시민의 제시어를 맞히면 보너스를 얻습니다.</p></div>';if($('#guessBtn'))$('#guessBtn').onclick=()=>socket.emit('submitLiarGuess',{guess:$('#guess').value},r=>!r.ok&&toast(r.error));}
if(state.phase==='result'){const names=state.voteResult?.liarIds.map(id=>state.players.find(p=>p.id===id)?.name).filter(Boolean).join(', ');a.innerHTML=`<div class="result"><h2>${state.voteResult?.caught?'🎉 검거 성공!':'😈 검거 실패!'}</h2><p>${state.voteResult?.roleMode==='spy'?'스파이':'라이어'}: <b>${esc(names||'')}</b></p>${state.voteResult?.roleMode==='spy'?`<p>시민 제시어: <b>${esc(state.voteResult.citizenWord||'')}</b> · 스파이 제시어: <b>${esc(state.voteResult.spyWord||'')}</b></p>`:state.voteResult?.citizenWord?`<p>정답: <b>${esc(state.voteResult.citizenWord)}</b></p>`:''}</div>`;}}
function renderTruth(){const turn=state.players.find(p=>p.id===state.truthTurnId);$('#mainCard').innerHTML=`<div class="eyebrow">${(state.settings.truthLevel||'normal').toUpperCase()}</div><div class="big">${turn?avatarHtml(turn.avatar,'mini-avatar'):''} ${esc(turn?.name||'')}님의 차례</div><div class="big question">${esc(state.truthQuestion)}</div>`;$('#actionArea').innerHTML='<p class="muted">디스코드에서 솔직하게 답해주세요. 불편한 질문은 방장이 다른 질문으로 넘길 수 있습니다.</p>'}
function mafiaChatBox(){if(!priv)return '';let title='',msgs=[];if(!priv.alive){title='💀 사망자 비밀 채팅';msgs=priv.deadChat||[]}else if(['mafia','spy'].includes(priv.role)&&(priv.mafiaTeamIds||[]).length>=2){title='🔒 마피아팀 비밀 채팅';msgs=priv.teamChat||[]}else return '';return `<div class="mafia-chat ${title.includes('마피아팀')?'mafia-team-chat':''}"><b>${title}</b><div class="mafia-chat-log">${msgs.map(m=>`<div><strong>${esc(m.name)}</strong> ${esc(m.text)}</div>`).join('')||'<span class="muted">아직 메시지가 없습니다.</span>'}</div><div class="mafia-chat-send"><input id="mafiaChatInput" maxlength="120" placeholder="비밀 메시지"><button id="mafiaChatSend">전송</button></div></div>`}
function bindMafiaChat(){const b=$('#mafiaChatSend'),i=$('#mafiaChatInput');if(!b||!i)return;const send=()=>{const text=i.value.trim();if(!text)return;socket.emit('mafiaChat',{text},r=>{if(!r.ok)toast(r.error);else{i.value='';i.focus()}})};b.onclick=send;i.onkeydown=e=>{if(e.key==='Enter')send()}}
function mafiaNoteKey(){return `sosoMafiaNote:${state?.code||''}:${me||''}`}
function renderMafia(){
 const p=state.players.find(x=>x.id===me),c=$('#mainCard'),a=$('#actionArea'),r=priv?.role;
 const candidate=state.players.find(x=>x.id===state.mafiaCandidateId);
 const ph=state.phase==='mafiaRoleReveal'?['rolephase','🎭 나의 역할을 확인하세요']:
   state.phase==='mafiaNight'?['night',`🌙 밤 · ${state.mafiaNightStep?role(state.mafiaNightStep)+' 행동':'행동 종료 대기'}`]:
   state.phase==='mafiaDay'?['day','☀️ 아침이 밝았습니다']:
   state.phase==='mafiaVote'?['day','⚖️ 처형 후보 투표']:
   state.phase==='mafiaDefense'?['day','🎙️ 최후 변론']:
   state.phase==='mafiaExecuteVote'?['day','⚖️ 최종 처형 투표']:
   state.phase==='terroristPick'?['day','💣 테러리스트의 마지막 선택']:['day','🏆 게임 결과'];
 const logs=state.mafiaLog.slice(-7);
 const desc=!p?.alive?'사망자 전용 관전자 화면과 비밀 채팅을 사용할 수 있습니다.':
   r==='mafia'?((priv?.mafiaTeamIds||[]).filter(id=>id!==me).length?'마피아팀과 협의해 밤에 제거할 대상을 선택하세요.':'밤에 제거할 대상을 선택하세요.'):r==='spy'?'마피아팀을 돕습니다. 경찰 조사에는 마피아가 아닌 것으로 나옵니다.':
   r==='police'?'밤에 한 명을 조사해 마피아인지 확인합니다.':r==='doctor'?'밤에 본인을 포함해 한 명을 보호할 수 있습니다.':
   r==='soldier'?'마피아의 밤 공격을 한 번 버틸 수 있습니다.':r==='reporter'?'게임 중 한 번 취재해 대상의 실제 직업을 다음 아침 모두에게 공개합니다.':
   r==='politician'?'낮 투표에서 내 표는 2표로 계산됩니다.':r==='terrorist'?'낮 처형 시 자신에게 투표한 한 명을 함께 데려갈 수 있습니다.':'토론과 투표로 마피아를 찾아내세요.';
 const spectator=(!p?.alive&&priv?.allRoles)?`<div class="spectator-board"><h3>👻 사후세계 관전자 화면</h3><p class="muted">살아있는 플레이어에게는 보이지 않습니다.</p><div class="spectator-grid">${state.players.map(x=>`<div class="spectator-role ${['mafia','spy'].includes(priv.allRoles[x.id])?'evil':''}">${avatarHtml(x.avatar)}<b>${esc(x.name)}</b><span>${roleIcon(priv.allRoles[x.id])} ${role(priv.allRoles[x.id])}</span><small>${x.alive?'생존':'💀 사망'}</small></div>`).join('')}</div></div>`:'';
 c.innerHTML=`<div class="mafia-scene ${ph[0]}"><div class="role-card ${r||''} ${state.phase==='mafiaRoleReveal'?'role-focus':''}"><div class="role-icon">${p?.alive?roleIcon(r):'👻'}</div><div class="role-name">${p?.alive?role(r):'사망한 플레이어'}</div><p>${state.phase==='mafiaRoleReveal'?'역할과 능력을 확인하고 기억하세요. 잠시 후 첫 번째 밤이 시작됩니다.':desc}</p>${priv?.loverName?`<p class="lover-info">💘 나의 연인: <b>${esc(priv.loverName)}</b></p>`:''}${priv?.inspection?`<p><b>🔎 최근 조사:</b> ${esc(priv.inspection.name)}님은 ${priv.inspection.isMafia?'🔴 마피아입니다!':'🔵 마피아가 아닙니다.'}</p>`:''}</div></div>${spectator}${logs.length?`<div class="mafia-log">${logs.map((x,i)=>`<div class="mafia-log-item ${i===logs.length-1?'latest':'past'}">${esc(x)}</div>`).join('')}</div>`:''}`;
 a.innerHTML='';
 if(state.phase==='mafiaRoleReveal')a.innerHTML='<div class="role-wait"><h3>역할 공개 중</h3><p>역할을 확인하고 기억해주세요. 잠시 후 첫 번째 밤이 시작됩니다.</p></div>';
 else if(state.phase==='mafiaNight'&&p?.alive){
   const canAct=(['mafia','doctor','police'].includes(r)||(r==='reporter'&&!priv?.reporterUsed));
   if(canAct&&!priv?.nightDone){
     const verb=r==='mafia'?'제거할':r==='doctor'?'보호할':r==='police'?'조사할':'취재할';
     const mafiaHint=r==='mafia'?(((priv?.mafiaTeamIds||[]).filter(id=>id!==me).length)?'마피아팀과 협의해 밤에 제거할 대상을 선택하세요.':'밤에 제거할 대상을 선택하세요.'):(r==='doctor'?'본인도 선택할 수 있습니다.':'');
     a.innerHTML=`<div class="night-action"><h3>${verb} 사람 선택</h3><p class="muted">${mafiaHint}</p><div class="vote-grid">${state.players.filter(x=>x.alive&&(r==='doctor'||x.id!==me)&&(r!=='mafia'||!(priv.mafiaTeamIds||[]).includes(x.id))).map(x=>`<button class="vote-btn night" data-id="${x.id}"><span class="face">${avatarHtml(x.avatar)}</span>${esc(x.name)}</button>`).join('')}</div></div>`;
     a.querySelectorAll('.night').forEach(b=>b.onclick=()=>{a.querySelectorAll('.night').forEach(x=>x.classList.remove('picked'));b.classList.add('picked');socket.emit('nightAction',{targetId:b.dataset.id},rr=>rr.ok?toast('선택을 완료했습니다.'):toast(rr.error))})
   }else a.innerHTML=`<div class="night-wait"><h3>밤이 진행되고 있습니다</h3><p>${priv?.nightDone?'내 행동을 완료했습니다. 아침이 될 때까지 기다려주세요.':'조용히 밤이 지나가기를 기다려주세요.'}</p></div>`;
 }
 if(state.phase==='mafiaDay')a.innerHTML='<div class="day-discussion"><h2>☀️ 자유 토론</h2><p>지난밤 결과를 토대로 디스코드에서 자유롭게 추리하세요.</p></div>';
 if(state.phase==='mafiaVote'&&p?.alive){voteUI(a,state.players);const grid=a.querySelector('.vote-grid');if(grid&&!state.votesSubmitted.includes(me)){const b=document.createElement('button');b.className='vote-btn abstain';b.innerHTML='<b>기권</b>';grid.appendChild(b);b.onclick=()=>socket.emit('vote',{targetId:'abstain'},rr=>rr.ok?toast('기권했습니다.'):toast(rr.error))}}
 if(state.phase==='mafiaVote'&&!p?.alive)a.innerHTML='<p>💀 사망한 플레이어는 투표할 수 없습니다.</p>';
 if(state.phase==='mafiaDefense')a.innerHTML=`<div class="defense-stage"><h2>🎙️ ${esc(candidate?.name||'처형 후보')}님의 최후 변론</h2><p>30초 동안 자신의 입장을 설명할 수 있습니다. 다른 플레이어는 변론을 들어주세요.</p></div>`;
 if(state.phase==='mafiaExecuteVote'&&p?.alive){
   const done=(state.executeVotesSubmitted||[]).includes(me);
   a.innerHTML=`<div class="execution-vote"><h2>${esc(candidate?.name||'후보')}님을 처형하시겠습니까?</h2><p>최후 변론을 들은 뒤 최종 결정을 내려주세요.</p>${done?'<b>✅ 최종 투표 완료</b>':`<div class="execute-buttons"><button id="executeYes" class="danger">처형</button><button id="executeNo" class="primary">살려준다</button></div>`}</div>`;
   if($('#executeYes'))$('#executeYes').onclick=()=>socket.emit('mafiaExecuteVote',{choice:'execute'},rr=>!rr.ok&&toast(rr.error));
   if($('#executeNo'))$('#executeNo').onclick=()=>socket.emit('mafiaExecuteVote',{choice:'spare'},rr=>!rr.ok&&toast(rr.error));
 }
 if(state.phase==='mafiaExecuteVote'&&!p?.alive)a.innerHTML='<p>👻 사망한 플레이어는 최종 처형 투표에 참여할 수 없습니다.</p>';
 if(state.phase==='terroristPick'){if(state.terroristPickId===me){a.innerHTML=`<h2>💣 함께 데려갈 사람 선택</h2><p>나에게 투표한 생존자 중 한 명을 선택하세요.</p><div class="vote-grid">${state.players.filter(x=>x.alive&&(priv.terroristCandidates||[]).includes(x.id)).map(x=>`<button class="terror-pick" data-id="${x.id}">${avatarHtml(x.avatar)} ${esc(x.name)}</button>`).join('')}</div>`;a.querySelectorAll('.terror-pick').forEach(b=>b.onclick=()=>socket.emit('terroristPick',{targetId:b.dataset.id},rr=>!rr.ok&&toast(rr.error)))}else a.innerHTML='<h3>💣 테러리스트가 마지막 대상을 선택하고 있습니다...</h3>'}
 if(state.phase==='mafiaResult')a.innerHTML=`<div class="result mafia-final"><h2>${esc(state.mafiaLog.at(-1)||'게임 종료')}</h2><h3>🎭 실제 직업 공개</h3><div class="role-reveal-grid">${state.players.map(x=>`<div>${avatarHtml(x.avatar)}<b>${esc(x.name)}</b><span>${roleIcon(x.rolePublic)} ${role(x.rolePublic)}</span></div>`).join('')}</div>${state.mafiaAwards?.length?`<h3>🏅 이번 게임 어워드</h3><div class="after-awards">${state.mafiaAwards.map(x=>`<span>${esc(x)}</span>`).join('')}</div>`:''}</div>`;
 a.insertAdjacentHTML('beforeend',mafiaChatBox());bindMafiaChat();renderMafiaSideNote()
}

function renderMafiaSideNote(){let box=document.getElementById('mafiaSideNote');const playerPanel=document.querySelector('#players')?.closest('.panel');if(state?.game!=='mafia'||state.phase==='lobby'){box?.remove();return}if(!box&&playerPanel){box=document.createElement('details');box.id='mafiaSideNote';box.className='mafia-side-note';playerPanel.appendChild(box)}if(!box)return;const note=localStorage.getItem(mafiaNoteKey())||'';box.innerHTML=`<summary>📝 내 추리노트</summary><textarea id="mafiaNoteSide" maxlength="1200" placeholder="나만 볼 수 있는 메모">${esc(note)}</textarea>`;const ta=$('#mafiaNoteSide');if(ta)ta.oninput=e=>localStorage.setItem(mafiaNoteKey(),e.target.value)}

// ---------- Secret Vault ----------
const geniusLobbyBgm=new Audio('/genius-lobby-bgm.mp3');geniusLobbyBgm.loop=true;geniusLobbyBgm.volume=.05;
function syncGeniusAudio(){const gl=state?.game==='genius'&&state.phase==='lobby',v=bgmVolume();geniusLobbyBgm.volume=v;if(bgmOn&&gl)geniusLobbyBgm.play().catch(()=>{});else geniusLobbyBgm.pause()}
// ---------- Word Chain ----------
const wcItemNames={time:'⏳ +5초',reverse:'🔄 방향전환',shield:'🛡️ 방어',bomb:'💣 시간폭탄',change:'🔤 글자변경'};
function renderWordchain(){const w=state.wordchain;if(!w)return;const myTurn=w.turnPlayerId===me,turnP=state.players.find(p=>p.id===w.turnPlayerId),winner=state.players.find(p=>p.id===w.winnerId);$('#mainCard').innerHTML=`<div class="wordchain-board"><div class="wc-top"><span>턴 ${w.turnNumber}</span><strong>${myTurn?'👉 내 차례':`⏳ ${esc(turnP?.name||'')}님 차례`}</strong><span>${w.direction===1?'진행 →':'← 진행'}</span></div><div class="wc-word">${esc(w.currentWord||'')}</div><div class="wc-next">다음 글자 <b>「${esc(w.required||'')}」</b></div>${w.lastAction?`<div class="wc-action">${esc(w.lastAction)}</div>`:''}</div>`;if(state.phase==='wordchainResult'){ $('#actionArea').innerHTML=`<div class="result"><h2>🏆 ${esc(winner?.name||'')} 승리!</h2><p>마지막까지 살아남았습니다.</p><div class="wc-history">${w.history.map(x=>`<span>${esc(x)}</span>`).join('<i>→</i>')}</div></div>`;return}const items=priv?.game==='wordchain'?(priv.items||[]):[];$('#actionArea').innerHTML=`<div class="wc-play"><div class="wc-input-wrap"><input id="wcInput" autocomplete="off" maxlength="12" placeholder="${myTurn?esc(w.required)+'(으)로 시작하는 단어':'내 차례를 기다리세요'}" ${myTurn?'':'disabled'}><button id="wcSubmit" class="primary" ${myTurn?'':'disabled'}>입력</button></div>${state.settings.wordchainMode==='item'?`<div class="wc-items"><b>내 아이템</b>${items.length?items.map(x=>`<button data-witem="${x}" ${myTurn?'':'disabled'}>${wcItemNames[x]||x}</button>`).join(''):'<span class="muted">사용 가능한 아이템이 없습니다.</span>'}</div>`:''}<div class="wc-history"><b>최근 단어</b>${w.history.map(x=>`<span>${esc(x)}</span>`).join('<i>→</i>')}</div>${w.challenge&&w.challenge.submitterId!==me&&!w.challenge.challengers.includes(me)?`<div class="wc-challenge"><span><b>"${esc(w.challenge.word)}"</b>이 실제 단어가 아니라고 생각하나요?</span><button id="wcChallenge" class="danger-soft">이의제기</button><small>${w.challenge.challengers.length}/${Math.max(1,state.players.filter(p=>p.connected&&!(w.eliminated?.[p.id])&&p.id!==w.challenge.submitterId).length)}명</small></div>`:''}<p class="muted">사전 제한 없이 자유롭게 입력합니다. 앞 글자와 중복 여부만 자동 검사하며, 이상한 단어는 다른 생존자 전원이 이의제기하면 제출자가 목숨 1개를 잃습니다.</p></div>`;if(myTurn){const submit=()=>{const v=$('#wcInput').value.trim();socket.emit('wordchainSubmit',{word:v},r=>{if(!r.ok){toast(r.error);$('#wcInput')?.focus()}})};$('#wcSubmit').onclick=submit;$('#wcInput').onkeydown=e=>{if(e.key==='Enter')submit()};setTimeout(()=>$('#wcInput')?.focus(),0)}if($('#wcChallenge'))$('#wcChallenge').onclick=()=>socket.emit('wordchainChallenge',{},r=>toast(r.ok?'이의제기했습니다.':r.error));$$('[data-witem]').forEach(b=>b.onclick=()=>socket.emit('wordchainItem',{item:b.dataset.witem},r=>!r.ok&&toast(r.error)))}

// ---------- Stock War ----------
const stockBgm=new Audio('/stock-war-bgm.mp3');stockBgm.loop=true;stockBgm.volume=.10;
let lastDealer='';function speakDealer(text,done){if(!text||!narrationOn){done?.();return}try{speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='ko-KR';const voices=speechSynthesis.getVoices();u.voice=voices.find(v=>v.lang?.toLowerCase().startsWith('ko')&&/natural|neural|sunhi|injoon|google|microsoft/i.test(v.name))||voices.find(v=>v.lang?.toLowerCase().startsWith('ko'))||null;u.rate=1.5;u.pitch=1.0;u.volume=narrationVolume();u.onend=u.onerror=()=>done?.();speechSynthesis.speak(u)}catch{done?.()}}
function syncStockAudio(){const v=bgmVolume();stockBgm.volume=v;if(state?.game==='stockwar'&&state.phase!=='lobby'&&bgmOn){stockBgm.play().catch(()=>{})}else stockBgm.pause();if(state?.game==='stockwar'&&state.stock?.dealer&&state.stock.dealer!==lastDealer){lastDealer=state.stock.dealer;const before=v;if(!stockBgm.paused)stockBgm.volume=Math.min(v,.015);speakDealer(lastDealer,()=>{stockBgm.volume=bgmVolume()})}}
function stockStars(n){return '★'.repeat(n||0)+'☆'.repeat(Math.max(0,5-(n||0)))}
function stockSpark(hist=[]){if(!hist.length)return'';const w=120,h=34,min=Math.min(...hist),max=Math.max(...hist),span=Math.max(1,max-min);const pts=hist.map((v,i)=>`${Math.round(i*(w/(Math.max(1,hist.length-1))))},${Math.round(h-(v-min)/span*h)}`).join(' ');return `<svg class="spark" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none"><polyline points="${pts}" fill="none" stroke="currentColor" stroke-width="2"/></svg>`}
function stockStageText(){if(!state?.stock)return'';const r=state.stock.round||1,neg=r<=2?'3분':r<=5?'3분 30초':r<=7?'4분':'4분 30초',info=r===8?'1분':'45초',result=r===8?'1분':'30초';const m={stockIntermission:'NEXT ROUND · 10초 후 다음 라운드가 시작됩니다.',stockInfoReview:`정보 확인 · ${info} — 새 정보와 시장 상황을 확인하세요.`,stockNegotiation:`전략·협상 · ${neg} — 음성룸과 비밀대화를 활용해 전략을 세우세요.`,stockAuction:'특급정보 경매 · 1분 — MAIN ROOM 전체 음성으로 진행됩니다.',stockTrade:'MARKET OPEN · 1분 30초 — 주식을 사고팔 수 있습니다. MAIN ROOM 전체 음성만 사용합니다.',stockResult:`결과 확인 · ${result} — 속보와 주가 변동을 확인하세요.`,stockBriefing:'룰 설명 — 모두 준비하면 시작합니다.'};return m[state.phase]||''}
function geniusGiftUi(){
 const g=state?.geniusGift;if(!g)return'';const winner=state.players.find(p=>p.id===g.winnerId),recipient=state.players.find(p=>p.id===g.recipientId);
 if(g.done)return `<div class="genius-gift-done">🎁 ${recipient?`${esc(winner?.name||'1위')}님이 ${esc(recipient.name)}님에게 가넷 1개를 선물했습니다.`:'가넷 보상 정산이 완료되었습니다.'}</div>`;
 if(g.winnerId!==me)return `<div class="genius-gift-wait">🎁 1위 ${esc(winner?.name||'')}님이 가넷 1개를 선물할 플레이어를 선택하는 중입니다.</div>`;
 const opts=(g.eligibleIds||[]).map(id=>state.players.find(p=>p.id===id)).filter(Boolean).map(p=>`<button data-genius-gift="${p.id}">${esc(p.name)}에게 1💎 선물</button>`).join('');
 return `<div class="genius-gift-box"><b>1위 특별 권한</b><p>꼴찌를 제외한 다른 플레이어 한 명에게 가넷 1개를 선물하세요.</p><div class="gift-options">${opts}</div></div>`
}
function bindGeniusGift(){ $$('[data-genius-gift]').forEach(b=>b.onclick=()=>socket.emit('geniusGiftGarnet',{targetId:b.dataset.geniusGift},r=>toast(r.ok?'가넷 1개를 선물했습니다.':r.error))) }
function stockMemoKey(){return `sosoStockMemo:${state?.code||'room'}`}
function bindStockPlayerActions(){
 if(state?.game!=='stockwar')return;
 $$('[data-stock-chat]').forEach(b=>b.onclick=e=>{e.stopPropagation();openStockWhisper(b.dataset.stockChat,false)});
 $$('[data-stock-pay]').forEach(b=>b.onclick=e=>{e.stopPropagation();openStockWhisper(b.dataset.stockPay,true)});
}
function openStockWhisper(targetId,focusPay=false){
 if(state?.game!=='stockwar')return;stockChatTarget=targetId;const p=state.players.find(x=>x.id===targetId);if(!p)return;
 const incoming=(priv?.messages||[]).filter(m=>!m.own&&m.from===targetId).length;stockReadCounts[targetId]=incoming;
 $('#stockWhisperTitle').textContent=`${p.name} · 비밀 대화`;
 renderStockWhisperModal();$('#stockWhisperModal').classList.remove('hidden');setTimeout(()=>$(focusPay?'#stockTransferAmount':'#stockWhisperInput')?.focus(),30);renderPlayers()
}
function renderStockWhisperModal(){
 if(!stockChatTarget)return;const p=state.players.find(x=>x.id===stockChatTarget);if(!p)return;const msgs=(priv?.messages||[]).filter(m=>(m.from===stockChatTarget||m.to===stockChatTarget));
 $('#stockWhisperHistory').innerHTML=msgs.map(m=>`<div class="stock-chat-row ${m.own?'mine':'theirs'}"><div class="stock-chat-bubble"><b>${m.own?'나':esc(m.name)}&nbsp;</b><span>${esc(m.text)}</span></div></div>`).join('')||'<span class="muted">아직 대화가 없습니다.</span>';
 const locked=state.phase==='stockTrade';$('#stockWhisperLock').classList.toggle('hidden',!locked);$('#stockWhisperInput').disabled=locked;$('#stockWhisperSend').disabled=locked;$('#stockWhisperInput').placeholder=locked?'시장 거래 중에는 비밀대화를 사용할 수 없습니다.':'비밀 메시지';
 const used=priv?.transferTo?.[stockChatTarget]||0,total=priv?.transferTotal||0;const box=$('#stockWhisperModal .stock-transfer-box small');if(box)box.textContent=`이번 라운드 송금 · 전체 ${total}/200C · ${p.name} ${used}/100C`;
 const h=$('#stockWhisperHistory');if(h)h.scrollTop=h.scrollHeight
}
function openStockShop(){renderStockShop();$('#stockShopModal').classList.remove('hidden')}
function renderStockShop(){const list=$('#stockShopList');if(!list)return;const offers=priv?.dealerOffers||[];list.innerHTML=offers.map(o=>`<div class="info-card"><small>${esc(o.grade)} · ${stockStars(o.stars||3)}</small><p><b>${esc(o.label||'시장 정보')}</b><br>내용은 구매 후 공개됩니다.</p><button class="compact" data-shop-buy="${o.id}" ${o.bought?'disabled':''}>${o.bought?'구매 완료':`${o.price}C로 구매`}</button></div>`).join('')||'<span class="muted">이번 라운드 판매 정보가 없습니다.</span>';$$('[data-shop-buy]').forEach(b=>b.onclick=()=>socket.emit('stockBuyDealerInfo',{offerId:b.dataset.shopBuy},r=>{toast(r.ok?'딜러 정보를 구매했습니다.':r.error);if(r.ok)setTimeout(renderStockShop,100)}))}
function stockRulePages(){return [
`<div class="stock-rule-page ppt"><div class="rule-kicker">PAGE 1 / 6 · STOCK WAR</div><h2>주식전쟁</h2><p class="rule-lead">정보를 얻고, 협상하고, 투자하여 <b>최고의 자산가</b>가 되십시오.</p><div class="rule-columns two"><div><strong>시작 자금</strong><p>모든 플레이어는 <b>1,000C</b>를 가지고 시작합니다. 매 게임 5개의 회사가 등장하며 모든 주식은 100C에서 시작합니다.</p></div><div><strong>승리 조건</strong><p>총 8라운드가 끝난 뒤 <b>현금 + 보유 주식 가치 - 부채</b>를 계산하여 순자산이 가장 높은 플레이어가 승리합니다.</p></div></div><div class="rule-callout">정보를 믿을지, 사람을 믿을지는 여러분의 선택입니다.</div></div>`,
`<div class="stock-rule-page ppt"><div class="rule-kicker">PAGE 2 / 6 · ROUND</div><h2>한 라운드는 이렇게 진행됩니다</h2><div class="rule-timeline"><div><b>01</b><strong>정보 확인 (R1~7 45초 / FINAL 1분)</strong><span>각자에게 서로 다른 비밀정보가 전달됩니다.</span></div><div><b>02</b><strong>전략·협상 (변동)</strong><span>정보를 교환하고, 동맹을 맺고, 투자 전략을 세우십시오.</span></div><div><b>03</b><strong>특급정보 경매 (1분)</strong><span>ROUND 3 · ROUND 6에서만 진행됩니다.</span></div><div><b>04</b><strong>시장 거래 (1분 30초)</strong><span>주식을 직접 매수하고 매도합니다.</span></div><div><b>05</b><strong>결과 확인 (R1~7 30초 / FINAL 1분)</strong><span>사건과 수급이 반영되어 새로운 주가가 결정됩니다.</span></div></div><div class="rule-note">전략·협상 시간은 R1~2 3분 / R3~5 3분30초 / R6~7 4분 / FINAL 4분30초로 진행됩니다.</div></div>`,
`<div class="stock-rule-page ppt"><div class="rule-kicker">PAGE 3 / 6 · INFORMATION</div><h2>여러분이 가진 정보는 서로 다릅니다</h2><p class="rule-lead">매 라운드 각 플레이어에게 서로 다른 비밀정보가 제공됩니다.</p><div class="rule-columns two"><div><strong>정보의 내용</strong><p>기업의 상승·하락 방향, 업종, 예상 변동폭, 시장 상황 등이 포함될 수 있으며 정보마다 출처와 구체성이 다릅니다.</p><p>추가 정보가 필요하다면 <b>딜러 정보상점</b>에서 구매할 수도 있습니다.</p></div><div><strong>블러핑 허용</strong><p>플레이어가 하는 말이 진실이라는 보장은 없습니다. 정보를 숨기거나 일부만 공개하거나 거짓말을 하는 것도 허용됩니다.</p><p><b>여러 정보를 조합해 진짜 시장의 흐름을 추리하십시오.</b></p></div></div></div>`,
`<div class="stock-rule-page ppt"><div class="rule-kicker">PAGE 4 / 6 · NEGOTIATION</div><h2>사람을 움직이는 것도 전략입니다</h2><div class="rule-columns"><div><strong>MAIN ROOM</strong><p>모든 플레이어가 함께 대화합니다.</p></div><div><strong>A · B · C ROOM</strong><p>같은 ROOM에 들어온 플레이어끼리만 음성으로 대화합니다. 누가 어느 ROOM에 있는지는 모두에게 공개됩니다.</p></div><div><strong>1:1 비밀대화</strong><p>원하는 플레이어에게 별도의 비밀 메시지를 보낼 수 있습니다.</p></div></div><div class="rule-note">협상의 대가로 코인을 송금할 수 있습니다. 라운드당 총 200C, 한 플레이어에게 최대 100C까지 가능합니다.<br><b>특급정보 경매와 시장 거래 중에는 전원이 MAIN ROOM으로 복귀합니다.</b></div></div>`,
`<div class="stock-rule-page ppt"><div class="rule-kicker">PAGE 5 / 6 · MARKET</div><h2>시장은 여러분의 행동에도 반응합니다</h2><p class="rule-lead">5개 회사의 주식을 직접 <b>매수 / 매도</b>할 수 있습니다.</p><div class="rule-formula"><span>기업 사건</span><i>+</i><span>시장 상황</span><i>+</i><span>플레이어의 실제 매수·매도</span><i>=</i><strong>주가 변동</strong></div><div class="rule-columns two"><div><strong>수급</strong><p>대량 매수가 몰리면 가격이 더 상승할 수 있고, 대량 매도가 발생하면 더 하락할 수 있습니다.</p></div><div><strong>격동장 · 경매</strong><p>일부 라운드에는 격동장과 반전이 발생합니다. ROUND 3 · ROUND 6에서는 1분간 특급정보 경매가 열리며 최고 입찰자가 정보를 독점합니다.</p></div></div></div>`,
`<div class="stock-rule-page ppt"><div class="rule-kicker">PAGE 6 / 6 · FINAL</div><h2>마지막까지 자산을 관리하십시오</h2><div class="rule-columns two"><div><strong>신용대출</strong><p>게임 중 한 번, 최대 <b>500C</b>를 대출할 수 있습니다. 이자는 20%이며 대출 사실은 공개됩니다. 원금과 이자는 게임 종료 시 자동 상환됩니다.</p></div><div><strong>PRIVATE TERMINAL</strong><p>현금, 주식, 부채, 순자산과 <b>현재 자신의 순위</b>를 확인할 수 있습니다.</p></div></div><div class="rule-note"><b>8라운드 종료 후 최종 순자산으로 순위를 결정합니다.</b><br>1위 💎3 / 2위 💎1 / 3위 💎1<br>1위는 꼴찌를 제외한 한 명에게 추가 가넷 1개를 선물합니다.</div><div class="rule-callout">정보를 이용하십시오. 사람을 의심하십시오. 그리고 가장 많은 자산을 남기십시오.</div></div>`
]}
function stockDetailedRulePages(){return [
...stockRulePages(),
`<div class="stock-rule-page ppt"><div class="rule-kicker">DETAIL · INFORMATION</div><h2>정보와 딜러 상점</h2><div class="rule-columns two"><div><strong>개인 정보</strong><p>매 라운드 방향·업종·변동폭·사건 관련 정보가 플레이어마다 다르게 지급됩니다. 출처와 신뢰도도 서로 다릅니다.</p></div><div><strong>딜러 정보상점</strong><p>라운드마다 판매 정보가 달라집니다. 코인으로 구매한 딜러 정보는 진실이지만, 다른 플레이어가 그 내용을 진실하게 전달한다는 보장은 없습니다.</p></div></div></div>`,
`<div class="stock-rule-page ppt"><div class="rule-kicker">DETAIL · MONEY</div><h2>송금 · 대출 · 경매</h2><div class="rule-columns"><div><strong>송금</strong><p>라운드 전체 200C, 동일 상대에게 100C가 한도입니다.</p></div><div><strong>대출</strong><p>게임당 1회, 최대 500C. 최종 상환액은 원금의 120%입니다.</p></div><div><strong>특급정보 경매</strong><p>3·6라운드 1분. 최고 입찰액이 즉시 차감되고 특급정보는 낙찰자에게만 공개됩니다.</p></div></div></div>`,
`<div class="stock-rule-page ppt"><div class="rule-kicker">DETAIL · VOICE</div><h2>음성 ROOM과 협상 제한</h2><p class="rule-lead">전략·협상 단계에는 MAIN / A / B / C ROOM을 자유롭게 이동할 수 있습니다.</p><div class="rule-note">누가 어느 방에 있는지는 공개되며, 같은 ROOM의 음성만 들립니다. 경매와 시장 거래가 시작되면 모두 MAIN ROOM으로 강제 복귀하고 비밀 ROOM 이동이 잠깁니다.</div></div>`,
`<div class="stock-rule-page ppt"><div class="rule-kicker">DETAIL · MARKET</div><h2>시장과 수급</h2><p class="rule-lead">주가는 기업 사건 + 시장 이벤트 + 플레이어 수급으로 결정됩니다.</p><div class="rule-note danger">대량 매수는 상승 압력을, 대량 매도는 하락 압력을 만듭니다. 격동장에서는 변동폭이 커지고 반전이 발생할 수 있습니다.</div></div>`
]}
function renderStockRuleSlide(page){const pages=stockRulePages();return pages[Math.max(0,Math.min(pages.length-1,page))]}
let stockRulesModalPage=0;
function openStockRules(page=0){stockRulesModalPage=page;renderStockRulesModal();$('#stockRulesModal')?.classList.remove('hidden')}
